363	func convertVisibilityToStore(visibility v1pb.Visibility) store.Visibility {
364		switch visibility {
365		case v1pb.Visibility_PROTECTED:
366			return store.Protected
367		case v1pb.Visibility_PUBLIC:
368			return store.Public
369		default:
370			return store.Private
371		}
372	}
